package org.apache.commons.math.stat.inference;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.distribution.ChiSquaredDistribution;
import org.apache.commons.math.distribution.ChiSquaredDistributionImpl;
import org.apache.commons.math.distribution.DistributionFactory;
import org.apache.commons.math.exception.MathAbsNotEqualException;
import org.apache.commons.math.exception.MathIllegalArgumentException;
import org.apache.commons.math.exception.NotStrictlyPositiveException;
import org.apache.commons.math.exception.NumberIsTooSmallException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class ChiSquareTestImpl_chiSquareTest_TriageGen1Test {

    private ChiSquareTestImpl testInstance;

    @Before
    public void setUp() {
        testInstance = new ChiSquareTestImpl();
    }

    /**
     * Tests a standard valid contingency table.
     * Expected behavior: returns a valid p-value.
     */
    @Test
    public void testChiSquareTest_ValidInput() throws Exception {
        long[][] counts = {
            {10, 20, 30},
            {20, 40, 60}
        };
        // In this specific case, row 2 is exactly 2x row 1, 
        // so chi-square statistic should be 0, p-value should be 1.0
        double pValue = testInstance.chiSquareTest(counts);
        assertEquals(1.0, pValue, 1e-10);
    }

    /**
     * Tests a case where the p-value is significantly different from 1.
     */
    @Test
    public void testChiSquareTest_SignificantDifference() throws Exception {
        long[][] counts = {
            {10, 10},
            {50, 5}
        };
        double pValue = testInstance.chiSquareTest(counts);
        assertTrue(pValue < 0.05);
    }

    /**
     * Tests input with null. 
     * Should throw IllegalArgumentException via checkArray.
     */
    @Test(expected = IllegalArgumentException.class)
    public void testChiSquareTest_NullInput() throws Exception {
        testInstance.chiSquareTest(null);
    }

    /**
     * Tests input with empty array.
     * Should throw IllegalArgumentException via checkArray.
     */
    @Test(expected = IllegalArgumentException.class)
    public void testChiSquareTest_EmptyArray() throws Exception {
        testInstance.chiSquareTest(new long[0][0]);
    }

    /**
     * Tests input with inconsistent row lengths.
     * Should throw IllegalArgumentException via checkArray.
     */
    @Test(expected = IllegalArgumentException.class)
    public void testChiSquareTest_InconsistentRows() throws Exception {
        long[][] counts = {
            {1, 2},
            {1, 2, 3}
        };
        testInstance.chiSquareTest(counts);
    }

    /**
     * Tests input where one dimension is 1 (Degrees of freedom = 0).
     * Depending on implementation of ChiSquaredDistribution, this might throw an exception 
     * or return a specific value. Since df = (r-1)*(c-1), if r=1 or c=1, df=0.
     * Apache Commons Math ChiSquaredDistribution typically requires df > 0.
     */
    @Test(expected = MathIllegalArgumentException.class)
    public void testChiSquareTest_ZeroDegreesOfFreedom() throws Exception {
        long[][] counts = {
            {10, 20, 30}
        };
        testInstance.chiSquareTest(counts);
    }

    /**
     * Tests input with negative values.
     * checkArray usually checks for non-negative elements.
     */
    @Test(expected = IllegalArgumentException.class)
    public void testChiSquareTest_NegativeValues() throws Exception {
        long[][] counts = {
            {10, -1},
            {20, 30}
        };
        testInstance.chiSquareTest(counts);
    }

    /**
     * Tests using a custom distribution via constructor.
     */
    @Test
    public void testChiSquareTest_WithCustomDistribution() throws Exception {
        ChiSquaredDistribution dist = new ChiSquaredDistribution(1.0);
        ChiSquareTestImpl customInstance = new ChiSquareTestImpl(dist);
        long[][] counts = {
            {5, 5},
            {5, 5}
        };
        // df = (2-1)*(2-1) = 1. chiSquare statistic = 0.
        // 1 - cumulativeProbability(0) for df=1 is 1.0
        double pValue = customInstance.chiSquareTest(counts);
        assertEquals(1.0, pValue, 1e-10);
    }
}
